import {prepareSemanticReview,recordSemanticReview,semanticReviewSessionJSON,semanticReviewHasRecords} from './review-core.mjs';
import {evaluationJSON} from './evaluation-core.mjs';
import {reviewHandoff,reviewHandoffMarkdown} from './review-report.mjs';
import {EVALUATION_CASES,CRITERIA} from './evaluation-fixtures.mjs';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session=null,selected='',dirty=false,busy=false;
function availability(){$('reviewer-label').disabled=busy||!!session?.review.reviews.some(r=>r.criteria.some(c=>c.result!=='Not assessed'));for(const field of document.querySelectorAll('#review-criteria select,#review-criteria textarea'))field.disabled=busy;for(const id of ['review-load','review-case','review-preview','review-export','session-preview','session-export','handoff-preview','handoff-export'])$(id).disabled=busy||dirty;for(const id of ['review-input','review-annotations'])$(id).disabled=busy;const row=session?.report.rows.find(r=>r.caseId===selected);$('review-record').disabled=busy||!row?.structuralValid;$('review-discard').disabled=busy||!dirty;$('review-dirty').textContent=dirty?'Unapplied edits. Record or discard them before changing the scenario, replacing candidates or exporting.':'Recorded decisions are held in this tab only.';}
function draw(){const row=session.report.rows.find(r=>r.caseId===selected),c=EVALUATION_CASES.find(c=>c.id===selected),r=session.review.reviews.find(r=>r.caseId===selected);
  const counts=session.report.counts;$('review-summary').textContent=`${counts.cases} cases · ${counts.structurallyValid} exact-citation checks valid · ${counts.needsSemanticReview} need semantic review · ${counts.semanticReviewFailed} failed review · ${counts.reviewerChecksSatisfied} reviewer checks satisfied. Missing/invalid cases remain in the total.`;
  $('reviewer-label').value=session.review.reviewerLabel;$('reviewer-label').disabled=session.review.reviews.some(r=>r.criteria.some(c=>c.result!=='Not assessed'));
  $('review-sources').innerHTML=`<h3>${esc(c.question)}</h3>${c.documents.map(d=>`<article><h3>${esc(d.publisher)}</h3><p class="muted">${esc(d.id)} · ${esc(d.reportedAt)} · ${esc(d.language)} · Source group: ${esc(d.originGroup)}</p><blockquote class="source-excerpt">${esc(d.excerpt)}</blockquote><p class="muted">${esc(d.accessNote)}</p></article>`).join('')}<h3>Authored review guidance</h3><p>${esc(c.guidance)}</p><p class="muted">These are visible authored fixtures, not an independently blinded evaluation.</p>`;
  $('review-output').innerHTML=`<p class="notice">${esc(row.outcome)}</p>${!row.structuralValid?`<p class="error">${esc(row.error)}</p>`:row.output.abstention?`<h3>Abstention</h3><p>${esc(row.output.abstention)}</p>`:row.output.proposals.map(p=>`<article class="ai-draft"><h3>Draft ${esc(p.id)}</h3><p>${esc(p.draftStatement)}</p><p>Limitations: ${esc(p.limitations)}</p>${p.citations.map(q=>`<p class="small-label">${esc(q.documentId)} · UTF-16 ${q.start}–${q.end}</p><blockquote class="source-excerpt">${esc(q.quote)}</blockquote>`).join('')}</article>`).join('')}`;
  $('review-criteria').innerHTML=row.structuralValid?r.criteria.map(v=>`<fieldset><legend>${esc(v.id)}</legend><p>${esc(CRITERIA[v.id])}</p><label for="criterion-${v.id}">Decision</label><select id="criterion-${v.id}" data-criterion="${v.id}">${['Not assessed','Pass','Fail'].map(s=>`<option${v.result===s?' selected':''}>${s}</option>`).join('')}</select><label for="note-${v.id}">Reason tied to the draft and sources</label><textarea id="note-${v.id}" maxlength="2000" rows="2">${esc(v.note)}</textarea></fieldset>`).join(''):'<p>Semantic review is unavailable for missing or structurally invalid output.</p>';
  $('review-form-error').textContent='';dirty=false;availability();
}
$('review-load').addEventListener('click',async()=>{if(busy||dirty)return;busy=true;availability();$('review-error').textContent='';try{const next=await prepareSemanticReview($('review-input').value,$('review-annotations').value);if(semanticReviewHasRecords(session)&&!confirm('Replace this review? Unexported recorded decisions and notes will be lost.'))return;session=next;selected=session.report.rows[0].caseId;$('review-case').innerHTML=session.report.rows.map(r=>`<option value="${r.caseId}">${esc(r.category)} / ${esc(r.caseId)}</option>`).join('');$('review-workspace').hidden=false;$('review-import').open=false;$('review-export-notice').textContent='';$('review-loaded').textContent=semanticReviewHasRecords(session)?'Recorded review restored after citation and fingerprint checks. Reviewer identity and judgments remain unverified.':'Candidates opened. All applicable criteria start Not assessed.';draw();}catch(e){$('review-error').textContent=e.message;}finally{busy=false;availability();}});
$('review-case').addEventListener('change',()=>{selected=$('review-case').value;draw();});
for(const id of ['semantic-form','reviewer-label'])$(id).addEventListener('input',()=>{if(!session||busy)return;dirty=true;availability();});
$('review-discard').addEventListener('click',()=>draw());
$('semantic-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;availability();$('review-form-error').textContent='';try{const criteria=[...document.querySelectorAll('[data-criterion]')].map(el=>({id:el.dataset.criterion,result:el.value,note:$(`note-${el.dataset.criterion}`).value}));const next=await recordSemanticReview(session,{caseId:selected,reviewerLabel:$('reviewer-label').value,criteria});session=next;$('review-export-notice').textContent='';draw();}catch(e){$('review-form-error').textContent=e.message;}finally{busy=false;availability();}});
async function outputRecord(bundle,download){
  if(busy||dirty||!session)return;busy=true;availability();$('review-export-notice').textContent='';
  try{const raw=bundle?await semanticReviewSessionJSON(session):evaluationJSON(session.review);
    if(download){const url=URL.createObjectURL(new Blob([raw+'\n'],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`ruthless-${bundle?'review-session':'semantic-review'}-${session.review.split}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);$('review-export-notice').textContent='Download requested. Confirm receipt in your browser; this app cannot verify that the file was saved.';}
    else{$('review-json-title').textContent=bundle?'Resumable review session':'Recorded review';$('review-json').value=raw;$('review-json-dialog').showModal();}
  }catch(e){$('review-export-notice').textContent=e.message;}finally{busy=false;availability();}
}
$('review-preview').addEventListener('click',()=>outputRecord(false,false));$('review-export').addEventListener('click',()=>outputRecord(false,true));
$('session-preview').addEventListener('click',()=>outputRecord(true,false));$('session-export').addEventListener('click',()=>outputRecord(true,true));
$('review-json-close').addEventListener('click',()=>$('review-json-dialog').close());
async function handoff(download=false){
  if(busy||dirty||!session)return;busy=true;availability();$('review-export-notice').textContent='';
  try{
    if(download){const raw=await reviewHandoffMarkdown(session),url=URL.createObjectURL(new Blob([raw],{type:'text/markdown; charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`ruthless-review-handoff-${session.review.split}.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);$('review-export-notice').textContent='Handoff download requested. Confirm receipt in your browser; this app cannot verify that the file was saved.';}
    else{
      const r=await reviewHandoff(session),c=r.counts;
      $('handoff-body').innerHTML=`<p class="notice">${esc(r.status)} · ${c.cases} cases in the selected suite.</p><div class="handoff-counts">${[['Missing outputs',c.missingOutputs],['Invalid outputs',c.invalidOutputs],['Failed review',c.semanticReviewFailed],['Awaiting review',c.needsSemanticReview],['Recorded checks satisfied',c.reviewerChecksSatisfied]].map(([label,n])=>`<div><strong>${n}</strong><span>${label}</span></div>`).join('')}</div><p>Candidate label (unverified): ${esc(r.candidateLabel)}<br>Reviewer label (unverified): ${esc(r.reviewerLabel||'None recorded')}</p><p class="muted">${esc(r.notice)}</p><details><summary>Source and output fingerprints</summary><p class="handoff-hash">Input/rubric: ${r.inputFingerprint}<br>Candidates: ${r.candidateFingerprint}</p></details>${r.rows.map(row=>`<article class="handoff-case"><div class="case-heading"><div><p class="small-label">${esc(row.caseId)} / ${esc(row.category)}</p><h3>${esc(row.question)}</h3></div><span class="chip">${esc(row.status)}</span></div>${row.error?`<p class="error">${esc(row.error)}</p>`:''}<p class="muted">Failed criteria: ${esc(row.failedCriteria.join(', ')||'None recorded')} · Unassessed criteria: ${esc(row.unassessedCriteria.join(', ')||'None recorded')}${!row.structuralValid?' · Recorded criterion labels cannot override this structural rejection.':''}</p><details><summary>Recorded decisions and source context</summary><p>${esc(row.guidance)}</p>${row.criteria.map(k=>`<div class="handoff-criterion"><strong>${esc(k.id)} / ${esc(k.result)}</strong><p>${esc(r.criteria[k.id])}</p><p>Note: ${esc(k.note||'No note recorded')}</p></div>`).join('')}${row.output?.abstention?`<h4>Abstention</h4><p>${esc(row.output.abstention)}</p>`:''}${(row.output?.proposals??[]).map(p=>`<h4>Draft ${esc(p.id)}</h4><p>${esc(p.draftStatement)}</p><p class="muted">Limitations: ${esc(p.limitations)}</p>${p.citations.map(q=>`<p class="small-label">${esc(q.documentId)} / UTF-16 ${q.start}–${q.end}</p><blockquote class="source-excerpt">${esc(q.quote)}</blockquote>`).join('')}`).join('')}<h4>Retained source context</h4>${row.documents.map(d=>`<p><strong>${esc(d.publisher)} / ${esc(d.id)}</strong><br>${esc(d.reportedAt)} · ${esc(d.language)} · Source group: ${esc(d.originGroup)}</p><blockquote class="source-excerpt">${esc(d.excerpt)}</blockquote><p class="muted">${esc(d.locator)} · ${esc(d.accessNote)}</p>`).join('')}</details><div class="actions"><button data-handoff-case="${row.caseId}">Open this case review</button></div></article>`).join('')}`;
      for(const button of document.querySelectorAll('[data-handoff-case]'))button.addEventListener('click',()=>{if(busy||dirty)return;$('handoff-dialog').close();selected=button.dataset.handoffCase;$('review-case').value=selected;draw();});
      $('handoff-dialog').showModal();
    }
  }catch(e){$('review-export-notice').textContent=e.message;}finally{busy=false;availability();}
}
$('handoff-preview').addEventListener('click',()=>handoff());$('handoff-export').addEventListener('click',()=>handoff(true));$('handoff-close').addEventListener('click',()=>$('handoff-dialog').close());
window.addEventListener('beforeunload',e=>{if(dirty||semanticReviewHasRecords(session)){e.preventDefault();e.returnValue='';}});
availability();
